using NUnit.Framework;using UnityEditor;using UnityEngine;using Rootborn.UI.StudentLife;using UnityEditor.SceneManagement;using System.Linq;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class HouseAndWorkshopComfyArtTests{
[SetUp]public void IsolateEditorScene(){for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)Assert.That(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty,Is.False,"Never discard an unsaved editor scene for art tests");EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity",OpenSceneMode.Single);}

[TestCase("Assets/Art/HousePixels/Furniture31/house_day_end_bed.png",120,120,60,60)][TestCase("Assets/Art/UrbanStreet/Buildings31/workshop_bench.png",96,96,48,4)]public void SpritePreservesReviewedWorldCanvasPivotAndCrispSampling(string path,int width,int height,int px,int py){var sprite=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(sprite,Is.Not.Null,"Reviewed Comfy export must be imported before scene binding");Assert.That(sprite.rect.size,Is.EqualTo(new Vector2(width,height)));Assert.That(sprite.pivot,Is.EqualTo(new Vector2(px,py)));Assert.That(sprite.pixelsPerUnit,Is.EqualTo(48));var importer=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(importer.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(importer.mipmapEnabled,Is.False);Assert.That(importer.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(importer.npotScale,Is.EqualTo(TextureImporterNPOTScale.None));var entry=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(entry,Is.Not.Null,"Each dedicated sprite must have its own stable address");}
[TestCase("Assets/Scenes/House.unity","StudentDayEndBoard","house_day_end_bed")][TestCase("Assets/Scenes/Town.unity","LocationVisit_location_workshop","workshop_bench")]public void SavedSceneUsesDedicatedSpriteAndRetainsExistingInteraction(string scenePath,string owner,string expected){var scene=EditorSceneManager.OpenPreviewScene(scenePath);try{var root=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Transform>(true)).Single(x=>x.name==owner);var renderer=root.Find("Visual").GetComponent<SpriteRenderer>();Assert.That(renderer.sprite.name,Is.EqualTo(expected));Assert.That(root.GetComponents<Collider2D>().Any(x=>x.isTrigger),Is.True,"Original interaction trigger remains");if(owner=="StudentDayEndBoard"){Assert.That(root.GetComponent<StudentDayEndInteractor>(),Is.Not.Null);Assert.That(root.Find("BedBody").GetComponent<Collider2D>().isTrigger,Is.False);Assert.That(renderer.sprite.bounds.size.x,Is.EqualTo(2.5f).Within(.0001f),"80/32 original canvas remains120/48");}else Assert.That(root.GetComponent<Rootborn.Game.StudentLife.LocationActivityInteractor>(),Is.Not.Null);}finally{EditorSceneManager.ClosePreviewScene(scene);}}}}
